-- ============================================================
-- 017_whatsapp_pricing_rates_seed.sql
-- Safe, rerunnable WhatsApp pricing-rate seed for whatsapp_pricing_rates.
--
-- IMPORTANT:
-- 1. Replace YOUR_ADMIN_EMAIL@example.com with the CRM admin email.
-- 2. These imported rates come from a reliable published table that says
--    it is sourced from Meta pricing rates, but they were not directly
--    extracted from Meta by this script. They are intentionally inserted
--    with verified_by_admin = false and last_verified_at = NULL.
-- 3. Verify important campaign markets against:
--    https://whatsappbusiness.com/products/platform-pricing/
-- 4. Actual billing is controlled by Meta. This CRM only estimates cost.
-- ============================================================

DO $$
DECLARE
  target_user_id UUID;
BEGIN
  SELECT id INTO target_user_id
  FROM auth.users
  WHERE email = 'YOUR_ADMIN_EMAIL@example.com'
  LIMIT 1;

  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'No Supabase auth user found for the seed email. Replace YOUR_ADMIN_EMAIL@example.com first.';
  END IF;

  INSERT INTO whatsapp_pricing_rates (
    user_id,
    country_name,
    iso_country_code,
    phone_country_code,
    currency,
    marketing_rate,
    utility_rate,
    authentication_rate,
    service_rate,
    source_url,
    source_note,
    official_rate_source_url,
    last_verified_at,
    verified_by_admin,
    notes,
    effective_from
  )
  VALUES
